103→void UW_FinaleScreen::DisplayProfile(const FTranslatorsProfile& Profile)
104→{
105→    if (!Profile.IsValid())
106→    {
107→        UE_LOG(LogTranslatorsBridge, Warning, TEXT("[W_FinaleScreen] Empty profile - nothing to display"));
108→        return;
109→    }
110→
111→    // Populate traits
112→    if (TraitsContainer)
113→    {
114→        TraitsContainer->ClearChildren();
115→
116→        for (const FTranslatorsTrait& Trait : Profile.Traits)
117→        {
118→            // Create a horizontal row: dimension | label | score bar | behavior
119→            UHorizontalBox* Row = NewObject<UHorizontalBox>(this);
120→
121→            // Dimension name (dim color, left-aligned)
122→            UTextBlock* DimText = NewObject<UTextBlock>(this);
123→            FString CleanDim = Trait.Dimension.Replace(TEXT("_"), TEXT(" "));
124→            DimText->SetText(FText::FromString(CleanDim));
125→            DimText->SetColorAndOpacity(FSlateColor(DimColor));
126→            DimText->SetFont(MakeFont(12));
127→
128→            UHorizontalBoxSlot* DimSlot = Row->AddChildToHorizontalBox(DimText);
129→            if (DimSlot)
130→            {
131→                DimSlot->SetPadding(FMargin(0.0f, 0.0f, 16.0f, 0.0f));
132→                DimSlot->SetSize(FSlateChildSize(ESlateSizeRule::Fill));
133→            }
134→
135→            // Label (cyan, bold-ish)
136→            UTextBlock* LabelText = NewObject<UTextBlock>(this);
137→            LabelText->SetText(FText::FromString(Trait.Label));
138→            LabelText->SetColorAndOpacity(FSlateColor(TraitLabelColor));
139→            LabelText->SetFont(MakeFont(14));
140→
141→            UHorizontalBoxSlot* LabelSlot = Row->AddChildToHorizontalBox(LabelText);
142→            if (LabelSlot)
143→            {
144→                LabelSlot->SetPadding(FMargin(0.0f, 0.0f, 16.0f, 0.0f));
145→                LabelSlot->SetSize(FSlateChildSize(ESlateSizeRule::Automatic));
146→            }
147→
148→            // Score (numeric)
149→            UTextBlock* ScoreText = NewObject<UTextBlock>(this);
150→            FString ScoreStr = FString::Printf(TEXT("%.0f%%"), Trait.Score * 100.0f);
151→            ScoreText->SetText(FText::FromString(ScoreStr));
152→            ScoreText->SetColorAndOpacity(FSlateColor(TraitValueColor));
153→            ScoreText->SetFont(MakeFont(12));
154→
155→            UHorizontalBoxSlot* ScoreSlot = Row->AddChildToHorizontalBox(ScoreText);
156→            if (ScoreSlot)
157→            {
158→                ScoreSlot->SetSize(FSlateChildSize(ESlateSizeRule::Automatic));
159→            }
160→
161→            UVerticalBoxSlot* RowSlot = TraitsContainer->AddChildToVerticalBox(Row);
162→            if (RowSlot)
163→            {
164→                RowSlot->SetPadding(FMargin(0.0f, 4.0f, 0.0f, 4.0f));
165→            }
166→
167→            // Behavior description (below the row, if present)
168→            if (!Trait.Behavior.IsEmpty())
169→            {
170→                UTextBlock* BehaviorText = NewObject<UTextBlock>(this);
171→                BehaviorText->SetText(FText::FromString(Trait.Behavior));
172→                BehaviorText->SetColorAndOpacity(FSlateColor(SubtitleColor));
173→                BehaviorText->SetAutoWrapText(true);
174→                BehaviorText->SetFont(MakeFont(11));
175→
176→                UVerticalBoxSlot* BehaviorSlot = TraitsContainer->AddChildToVerticalBox(BehaviorText);
177→                if (BehaviorSlot)
178→                {
179→                    BehaviorSlot->SetPadding(FMargin(20.0f, 0.0f, 0.0f, 8.0f));
180→                }
181→            }
182→        }
183→    }
184→
185→    // Populate insights
186→    if (InsightsContainer)
187→    {
188→        InsightsContainer->ClearChildren();
189→
190→        for (const FString& Insight : Profile.Insights)
191→        {
192→            UTextBlock* InsightText = NewObject<UTextBlock>(this);
193→            FString BulletInsight = FString::Printf(TEXT("  %s"), *Insight);
194→            InsightText->SetText(FText::FromString(BulletInsight));
195→            InsightText->SetColorAndOpacity(FSlateColor(InsightColor));
196→            InsightText->SetAutoWrapText(true);
197→            InsightText->SetFont(MakeFont(13));
198→
199→            UVerticalBoxSlot* InsightSlot = InsightsContainer->AddChildToVerticalBox(InsightText);
200→            if (InsightSlot)
201→            {
202→                InsightSlot->SetPadding(FMargin(0.0f, 3.0f, 0.0f, 3.0f));
203→            }
204→        }
205→    }
206→
207→    // Checksum/anchor
208→    if (ChecksumText)
209→    {
210→        FString ChecksumDisplay;
211→        if (!Profile.Anchor.IsEmpty())
212→        {
213→            ChecksumDisplay = Profile.Anchor;
214→        }
215→        else if (!Profile.Checksum.IsEmpty())
216→        {
217→            ChecksumDisplay = FString::Printf(TEXT("[TRANSLATORS:%s]"), *Profile.Checksum);
218→        }
219→
220→        if (!ChecksumDisplay.IsEmpty())
221→        {
222→            ChecksumText->SetText(FText::FromString(ChecksumDisplay));
223→            ChecksumText->SetVisibility(ESlateVisibility::Visible);
224→        }
225→    }
226→
227→    UE_LOG(LogTranslatorsBridge, Log, TEXT("[W_FinaleScreen] Displayed profile: %d traits, %d insights"),
228→        Profile.Traits.Num(), Profile.Insights.Num());
229→}
