232→void UW_FinaleScreen::BuildWidgetTree()
233→{
234→    // Create full-screen canvas
235→    UCanvasPanel* RootCanvas = WidgetTree->ConstructWidget<UCanvasPanel>(UCanvasPanel::StaticClass(), TEXT("RootCanvas"));
236→    WidgetTree->RootWidget = RootCanvas;
237→
238→    // Full-screen background
239→    BackgroundBorder = WidgetTree->ConstructWidget<UBorder>(UBorder::StaticClass(), TEXT("BackgroundBorder"));
240→    BackgroundBorder->SetBrushColor(BackgroundColor);
241→
242→    UCanvasPanelSlot* BorderSlot = RootCanvas->AddChildToCanvas(BackgroundBorder);
243→    if (BorderSlot)
244→    {
245→        BorderSlot->SetAnchors(FAnchors(0.0f, 0.0f, 1.0f, 1.0f));
246→        BorderSlot->SetOffsets(FMargin(0.0f));
247→    }
248→
249→    // Scrollable content area (centered, constrained width)
250→    UScrollBox* ScrollArea = WidgetTree->ConstructWidget<UScrollBox>(UScrollBox::StaticClass(), TEXT("ScrollArea"));
251→
252→    UCanvasPanelSlot* ScrollSlot = RootCanvas->AddChildToCanvas(ScrollArea);
253→    if (ScrollSlot)
254→    {
255→        // Center with padding
256→        ScrollSlot->SetAnchors(FAnchors(0.15f, 0.05f, 0.85f, 0.95f));
257→        ScrollSlot->SetOffsets(FMargin(0.0f));
258→    }
259→
260→    // Main content vertical box
261→    UVerticalBox* ContentBox = WidgetTree->ConstructWidget<UVerticalBox>(UVerticalBox::StaticClass(), TEXT("ContentBox"));
262→    ScrollArea->AddChild(ContentBox);
263→
264→    // === Title: "Your Cognitive Profile" ===
265→    TitleText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("TitleText"));
266→    TitleText->SetText(NSLOCTEXT("TranslatorsBridge", "FinaleScreen.Title", "Your Cognitive Profile"));
267→    TitleText->SetColorAndOpacity(FSlateColor(TitleColor));
268→    TitleText->SetJustification(ETextJustify::Center);
269→
270→    TitleText->SetFont(MakeFont(36));
271→
272→    UVerticalBoxSlot* TitleSlot = ContentBox->AddChildToVerticalBox(TitleText);
273→    if (TitleSlot)
274→    {
275→        TitleSlot->SetPadding(FMargin(0.0f, 20.0f, 0.0f, 8.0f));
276→        TitleSlot->SetHorizontalAlignment(HAlign_Center);
277→    }
278→
279→    // === Subtitle ===
280→    SubtitleText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("SubtitleText"));
281→    SubtitleText->SetText(NSLOCTEXT("TranslatorsBridge", "FinaleScreen.Subtitle", "Your cognitive profile has been generated."));
282→    SubtitleText->SetColorAndOpacity(FSlateColor(SubtitleColor));
283→    SubtitleText->SetJustification(ETextJustify::Center);
284→
285→    SubtitleText->SetFont(MakeFont(16));
286→
287→    UVerticalBoxSlot* SubtitleSlot = ContentBox->AddChildToVerticalBox(SubtitleText);
288→    if (SubtitleSlot)
289→    {
290→        SubtitleSlot->SetPadding(FMargin(0.0f, 0.0f, 0.0f, 30.0f));
291→        SubtitleSlot->SetHorizontalAlignment(HAlign_Center);
292→    }
293→
294→    // === Traits section header ===
295→    UTextBlock* TraitsHeader = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("TraitsHeader"));
296→    TraitsHeader->SetText(NSLOCTEXT("TranslatorsBridge", "FinaleScreen.DimensionsHeader", "DIMENSIONS"));
297→    TraitsHeader->SetColorAndOpacity(FSlateColor(DimColor));
298→
299→    TraitsHeader->SetFont(MakeFont(12));
300→
301→    UVerticalBoxSlot* TraitsHeaderSlot = ContentBox->AddChildToVerticalBox(TraitsHeader);
302→    if (TraitsHeaderSlot)
303→    {
304→        TraitsHeaderSlot->SetPadding(FMargin(0.0f, 0.0f, 0.0f, 10.0f));
305→    }
306→
307→    // === Traits container (populated dynamically) ===
308→    TraitsContainer = WidgetTree->ConstructWidget<UVerticalBox>(UVerticalBox::StaticClass(), TEXT("TraitsContainer"));
309→
310→    UVerticalBoxSlot* TraitsSlot = ContentBox->AddChildToVerticalBox(TraitsContainer);
311→    if (TraitsSlot)
312→    {
313→        TraitsSlot->SetPadding(FMargin(0.0f, 0.0f, 0.0f, 30.0f));
314→    }
315→
316→    // === Insights section header ===
317→    UTextBlock* InsightsHeader = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("InsightsHeader"));
318→    InsightsHeader->SetText(NSLOCTEXT("TranslatorsBridge", "FinaleScreen.InsightsHeader", "INSIGHTS"));
319→    InsightsHeader->SetColorAndOpacity(FSlateColor(DimColor));
320→
321→    InsightsHeader->SetFont(MakeFont(12));
322→
323→    UVerticalBoxSlot* InsightsHeaderSlot = ContentBox->AddChildToVerticalBox(InsightsHeader);
324→    if (InsightsHeaderSlot)
325→    {
326→        InsightsHeaderSlot->SetPadding(FMargin(0.0f, 0.0f, 0.0f, 10.0f));
327→    }
328→
329→    // === Insights container (populated dynamically) ===
330→    InsightsContainer = WidgetTree->ConstructWidget<UVerticalBox>(UVerticalBox::StaticClass(), TEXT("InsightsContainer"));
331→
332→    UVerticalBoxSlot* InsightsSlot = ContentBox->AddChildToVerticalBox(InsightsContainer);
333→    if (InsightsSlot)
334→    {
335→        InsightsSlot->SetPadding(FMargin(0.0f, 0.0f, 0.0f, 30.0f));
336→    }
337→
338→    // === Checksum/anchor (hidden until profile loaded) ===
339→    ChecksumText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("ChecksumText"));
340→    ChecksumText->SetText(FText::FromString(TEXT("")));
341→    ChecksumText->SetColorAndOpacity(FSlateColor(DimColor));
342→    ChecksumText->SetJustification(ETextJustify::Center);
343→    ChecksumText->SetVisibility(ESlateVisibility::Collapsed);
344→
345→    ChecksumText->SetFont(MakeFont(11));
346→
347→    UVerticalBoxSlot* ChecksumSlot = ContentBox->AddChildToVerticalBox(ChecksumText);
348→    if (ChecksumSlot)
349→    {
350→        ChecksumSlot->SetPadding(FMargin(0.0f, 0.0f, 0.0f, 16.0f));
351→        ChecksumSlot->SetHorizontalAlignment(HAlign_Center);
352→    }
353→
354→    // === Export path (hidden until set) ===
355→    PathText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("PathText"));
356→    PathText->SetText(FText::FromString(TEXT("")));
357→    PathText->SetColorAndOpacity(FSlateColor(DimColor));
358→    PathText->SetJustification(ETextJustify::Center);
359→    PathText->SetVisibility(ESlateVisibility::Collapsed);
360→
361→    PathText->SetFont(MakeFont(11));
362→
363→    UVerticalBoxSlot* PathSlot = ContentBox->AddChildToVerticalBox(PathText);
364→    if (PathSlot)
365→    {
366→        PathSlot->SetHorizontalAlignment(HAlign_Center);
367→    }
368→
369→    UE_LOG(LogTranslatorsBridge, Log, TEXT("[W_FinaleScreen] Built programmatic widget tree with profile display"));
370→}
